---
name: build-mosaic-gallery
description: >-
  Use when you need to create, rebuild, preview or deploy a photo-mosaic gallery
  website (photos arranged as a shape such as a heart, circle, star, state
  outline or initials) from an owner's photos - X/Twitter posts, a folder, chat
  uploads or a Drive/Photos export. Contains the complete tested code
  (gallery.py + template.html), the exact commands, and the checks. Used by
  gallery-getting-started (first build) and daily-gallery-update (incremental).
---
# Build a mosaic gallery

Result: a static site (`index.html`, `/play`, `atlas.jpg`, `tiles.json`, `card.png` share image) where every kept photo is a tile; tiles fly in, ripple, magnify under the finger/mouse, tap = preview card, tap the card photo = lightbox (+ "Open post on X" link when the photo came from X). Everything (title, caption, accent colour, shape, handle, count text, share card) is generated from `config.json` and the real photo count.

## 0. Setup (once)
Work dir `~/gallery` (called `$G`). Needs python3, `pip install pillow numpy` (optional `pillow-heif` for iPhone HEIC), node/npm for Vercel, google-chrome/chromium for screenshots.
Write the two files below **verbatim** into `$G` (`gallery.py`, `template.html`) - or, if this skill is a file on disk: `python3 -c "import re,sys,os;s=open(sys.argv[1]).read();d=os.path.expanduser(sys.argv[2]);os.makedirs(d,exist_ok=True);[open(os.path.join(d,n),'w').write(b) for n,b in re.findall(r'^'+chr(96)*3+r'\w+ (\S+)\n(.*?)^'+chr(96)*3,s,re.S|re.M)]" /path/to/this/SKILL.md ~/gallery`.

```python gallery.py
#!/usr/bin/env python3
"""gallery.py - photo-mosaic gallery kit. Run from the work dir (the folder holding this file and template.html).
Subcommands: config fetch dedupe sheets apply build remove verify deploy live-check rollback  (see --help of each)."""
import argparse, datetime, hashlib, html, json, math, os, random, re, shutil, subprocess, sys, time, urllib.parse, urllib.request
import numpy as np
from PIL import Image, ImageDraw, ImageFont, ImageOps
ROOT = os.path.dirname(os.path.abspath(__file__)); os.chdir(ROOT)
UA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126 Safari/537.36"
DEFAULTS = dict(title='My Gallery', caption='', accent='#2f7bd9', handle='', source='folder', theme='', shape='circle', shape_name='',
                grid=0, url='', project='', player=False, since='', until='')
NEAR, LOOSE, THUMB, ATLAS = 6, 16, 160, 96
def J(p, d=None): return json.load(open(p)) if os.path.exists(p) else d
def dump(o, p, **k): json.dump(o, open(p, 'w'), **k)
def log(*a): print(*a, flush=True)
def die(m, c=1): print('ERROR:', m, file=sys.stderr); sys.exit(c)
def cfg():
    c = dict(DEFAULTS); c.update(J('config.json', {})); return c
def sha(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for b in iter(lambda: f.read(1 << 20), b''): h.update(b)
    return h.hexdigest()
def load(path):
    try:
        import pillow_heif; pillow_heif.register_heif_opener()
    except Exception: pass
    return ImageOps.exif_transpose(Image.open(path)).convert('RGB')
def hashes(path):
    im = load(path).convert('L')
    a = np.asarray(im.resize((32, 32), Image.LANCZOS), dtype=float)          # phash (DCT 8x8 low freq)
    n = 32; k = np.cos(np.pi * (2 * np.arange(n)[None, :] + 1) * np.arange(n)[:, None] / (2 * n)); d = (k @ a @ k.T)[:8, :8]
    ph = int(''.join('1' if v > np.median(d) else '0' for v in d.flatten()), 2)
    b = np.asarray(im.resize((9, 8), Image.LANCZOS), dtype=float); dh = int(''.join('1' if v else '0' for v in (b[:, 1:] > b[:, :-1]).flatten()), 2)
    return dict(phash=format(ph, '016x'), dhash=format(dh, '016x'))
def ham(a, b): return bin(int(a, 16) ^ int(b, 16)).count('1')
def font(s):
    for p in ('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', '/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf', '/Library/Fonts/Arial Bold.ttf', 'C:/Windows/Fonts/arialbd.ttf'):
        if os.path.exists(p): return ImageFont.truetype(p, s)
    return ImageFont.load_default(size=s)
def http(url, tries=4, accept='application/json', binary=False):
    for a in range(tries):
        try:
            r = urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': UA, 'Accept': accept}), timeout=60); b = r.read()
            return b if binary else json.loads(b)
        except Exception as e: log(f'  retry {a} {url[:70]} {str(e)[:60]}'); time.sleep(2 * (a + 1))
    return None

# ------------------------------------------------------------------ config
def cmd_config(a):
    c = J('config.json', {})
    for kv in a.kv:
        k, _, v = kv.partition('=')
        if k not in DEFAULTS: die(f'unknown key {k}; keys: {sorted(DEFAULTS)}')
        c[k] = (v.lower() in ('1', 'true', 'yes') if isinstance(DEFAULTS[k], bool) else int(v) if isinstance(DEFAULTS[k], int) else v.rstrip('/') if k == 'url' else v)
    dump(c, 'config.json', indent=1); log(json.dumps(cfg(), indent=1))

# ------------------------------------------------------------------ fetch
def posts_fx(res, handle):
    out = []
    for r in res:
        if (r.get('author') or {}).get('screen_name', '').lower() != handle.lower() or r.get('replying_to') or r.get('replying_to_status') or r.get('reposted_by'): continue
        out.append((r['id'], r['created_timestamp'], [p['url'] for p in ((r.get('media') or {}).get('photos') or []) if p.get('type') == 'photo'], r.get('text') or ''))
    return out
def posts_api(j):  # X API v2 JSON {data:[...], includes:{media:[...]}} as returned by the X read tools
    med = {x['media_key']: x for x in (j.get('includes') or {}).get('media', [])}; out = []
    for p in j.get('data') or []:
        if any(t.get('type') in ('replied_to', 'retweeted') for t in p.get('referenced_tweets') or []) or p.get('in_reply_to_user_id'): continue
        ts = datetime.datetime.fromisoformat(p['created_at'].replace('Z', '+00:00')).timestamp()
        out.append((p['id'], ts, [med[k]['url'] for k in (p.get('attachments') or {}).get('media_keys', []) if k in med and med[k].get('type') == 'photo'], p.get('text') or ''))
    return out
def exif_date(path, fallback):
    try:
        e = Image.open(path).getexif(); s = (e.get_ifd(0x8769).get(36867) or e.get(306))
        return datetime.datetime.strptime(s, '%Y:%m:%d %H:%M:%S').isoformat()
    except Exception: return datetime.datetime.fromtimestamp(fallback).isoformat()
def cmd_fetch(a):
    c = cfg(); man = J('manifest.json', []); known = {m['key'] for m in man}; os.makedirs('photos', exist_ok=True)
    since = a.since or c['since']; until = a.until or c['until']; D = lambda x: datetime.datetime.fromisoformat(x).timestamp()
    cut = D(since) if since else 0                      # folder: only the date window (known files are skipped by hash)
    if not a.folder and man and not a.since: cut = max(D(m['date']) for m in man) - a.days_back * 86400   # X: resume near the newest known photo
    end = datetime.datetime.fromisoformat(until).timestamp() + 86400 if until else 1e12
    cands = []; nk = 0
    if a.folder:
        exts = ('.jpg', '.jpeg', '.png', '.webp', '.heic')
        for dp, _, fs in os.walk(a.folder):
            for f in sorted(fs):
                if not f.lower().endswith(exts) or os.path.abspath(dp).startswith(os.path.abspath('site')): continue
                src = os.path.join(dp, f); h = sha(src)
                if 'sha:' + h in known: nk += 1; continue
                d = exif_date(src, os.path.getmtime(src)); ts = datetime.datetime.fromisoformat(d).timestamp()
                if not cut <= ts < end: continue
                dst = f'photos/{d[:10]}_{h[:10]}{os.path.splitext(f)[1].lower()}'
                if not os.path.exists(dst): shutil.copy2(src, dst)
                cands.append(dict(key='sha:' + h, post_id='', date=d, file=dst, link='', text=f, src='folder'))
    else:
        handle = a.handle or c['handle'] or die('no handle: config handle=NAME or --handle')
        posts = []
        if a.x_json:
            for f in a.x_json: posts += posts_api(J(f))
        else:
            cursor = None
            for page in range(150):
                d = http('https://api.fxtwitter.com/2/profile/%s/statuses' % handle + (('?cursor=' + urllib.parse.quote(cursor, safe='')) if cursor else ''))
                if d is None: die('fxtwitter unavailable. Fallback: save the X read tool results (user posts, exclude replies+retweets, expansions attachments.media_keys, media.fields url,type, tweet.fields created_at,referenced_tweets) to a file and rerun with --x-json FILE', 2)
                res = d.get('results') or []; posts += posts_fx(res, handle); ts = [r['created_timestamp'] for r in res if r.get('created_timestamp')]
                cursor = (d.get('cursor') or {}).get('bottom'); log(f'  page {page+1}: {len(res)} posts')
                if not res or not cursor or (ts and min(ts) < cut): break
                time.sleep(.3)
        seen = set()
        for pid, ts, urls, text in sorted(posts, key=lambda p: p[1]):
            if not cut <= ts < end: continue
            for u in urls:
                b = u.split('?')[0]
                if b in known or b in seen: continue
                seen.add(b); dt = datetime.datetime.fromtimestamp(ts).isoformat(); fn = f'photos/{dt[:10]}_{pid}_{os.path.basename(b)}'
                if not os.path.exists(fn) or not os.path.getsize(fn):
                    data = http(b + '?name=orig', binary=True, accept='image/*')
                    if data: open(fn, 'wb').write(data)
                try: Image.open(fn).verify()
                except Exception: log('  download failed, skipping', b); continue
                cands.append(dict(key=b, post_id=str(pid), date=dt, file=fn, link=f'https://x.com/{handle}/status/{pid}', text=text[:100].replace('\n', ' '), src='x'))
    for x in cands:
        try: x.update(sha256=sha(x['file']), **hashes(x['file']))
        except Exception as e: log('  unreadable image', x['file'], e); x['bad'] = True
    cands = [x for x in cands if not x.get('bad')]
    log(f'{len(cands)} new candidate photos' + (f' ({nk} files already known, ignored)' if nk else '')); dump(cands, 'pending_raw.json'); cmd_dedupe(a); cmd_sheets(a)

# ------------------------------------------------------------------ dedupe + review sheets
def cmd_dedupe(a):
    """Compare pending photos with EVERY photo ever seen (kept and skipped) and within the batch.
    exact (same sha256 / media key) -> dropped; near (phash<=6 AND dhash<=6) -> suggest_dup (default skip); both<=16 -> listed in `similar` for visual review."""
    man = J('manifest.json', []); raw = J('pending_raw.json', []); pend = []; dropped = 0
    refs = [('m%d' % i, m) for i, m in enumerate(man) if m.get('phash')]
    shas = {m['sha256']: 'm%d' % i for i, m in enumerate(man) if m.get('sha256')}
    for x in raw:
        if x['sha256'] in shas: dropped += 1; log(f"  exact duplicate of {shas[x['sha256']]}: {x['file']}"); continue
        x['n'] = len(pend); x['similar'] = []; x['suggest_dup'] = False
        for r, m in refs + [('p%d' % p['n'], p) for p in pend]:
            dp, dd = ham(x['phash'], m['phash']), ham(x['dhash'], m['dhash'])
            if dp <= LOOSE and dd <= LOOSE:
                x['similar'].append(dict(ref=r, file=m['file'], dist=[dp, dd], decision=m.get('decision', 'pending'))); x['suggest_dup'] |= dp <= NEAR and dd <= NEAR
        shas[x['sha256']] = 'p%d' % x['n']; pend.append(x)
    dump(pend, 'pending.json', indent=1)
    log(json.dumps(dict(pending=len(pend), exact_duplicates_dropped=dropped, suggested_duplicates=sum(x['suggest_dup'] for x in pend), with_similar=sum(bool(x['similar']) for x in pend))))

def cmd_sheets(a):
    pend = J('pending.json', []); os.makedirs('sheets', exist_ok=True)
    for f in os.listdir('sheets'): os.remove('sheets/' + f)
    T, per, cols, F = 300, 20, 5, font(26)
    def thumb(path, size=T - 6):
        t = ImageOps.contain(load(path), (size, size)); b = Image.new('RGB', (T, T), (20, 20, 20)); b.paste(t, ((T - t.width) // 2, (T - t.height) // 2)); return b
    for s in range(0, len(pend), per):
        grp = pend[s:s + per]; sh = Image.new('RGB', (cols * T, math.ceil(len(grp) / cols) * T), (20, 20, 20)); d = ImageDraw.Draw(sh)
        for i, x in enumerate(grp):
            X, Y = (i % cols) * T, (i // cols) * T; sh.paste(thumb(x['file']), (X, Y)); d.rectangle([X + 3, Y + 3, X + 80, Y + 34], fill='black')
            d.text((X + 6, Y + 4), str(x['n']), fill='red' if x['suggest_dup'] else 'yellow', font=F)
        sh.save(f'sheets/pending_{s // per:02d}.jpg', quality=85)
    pairs = [(x, y) for x in pend for y in x['similar'][:2]]          # left = new photo, right = the existing/earlier look-alike
    for s in range(0, len(pairs), 12):
        grp = pairs[s:s + 12]; sh = Image.new('RGB', (min(3, len(grp)) * 2 * T, math.ceil(len(grp) / 3) * T), (60, 0, 0)); d = ImageDraw.Draw(sh)
        for i, (x, y) in enumerate(grp):
            X, Y = (i % 3) * 2 * T, (i // 3) * T; sh.paste(thumb(x['file']), (X, Y)); sh.paste(thumb(y['file']), (X + T, Y))
            d.rectangle([X + 3, Y + 3, X + T * 2 - 3, Y + 34], fill='black'); d.text((X + 6, Y + 4), f"new #{x['n']} vs {y['ref']} ({y['decision']}) dist {y['dist']}", fill='yellow', font=font(20))
        sh.save(f'sheets/dupes_{s // 12:02d}.jpg', quality=85)
    log('sheets:', sorted(os.listdir('sheets')))

# ------------------------------------------------------------------ shapes -> mask -> cells
def shape_mask(spec):
    k, _, arg = spec.partition(':'); S = 800; M = Image.new('L', (S, S)); d = ImageDraw.Draw(M)
    if k == 'heart':
        t = np.linspace(0, 2 * math.pi, 200); d.polygon(list(zip(16 * np.sin(t) ** 3 * 24 + 400, 400 - (13 * np.cos(t) - 5 * np.cos(2 * t) - 2 * np.cos(3 * t) - np.cos(4 * t)) * 24)), fill=255)
    elif k == 'circle': d.ellipse([0, 0, S - 1, S - 1], fill=255)
    elif k == 'square': d.rectangle([0, 0, S - 1, S - 1], fill=255)
    elif k == 'star': d.polygon([(S / 2 + (S / 2 if i % 2 == 0 else S * .2) * math.sin(i * math.pi / 5), S / 2 - (S / 2 if i % 2 == 0 else S * .2) * math.cos(i * math.pi / 5)) for i in range(10)], fill=255)
    elif k == 'bird':  # songbird on a branch, polygon in 0-100 coords
        P = [(40,3),(45,9),(47,16),(51,23),(60,29),(68,37),(74,47),(77,57),(77,65),(85,82),(92,96),(82,98),(69,75),(61,74),(50,76),(37,75),(26,68),(19,57),(17,46),(21,37),(20,33),(6,28),(20,22),(26,17),(32,9)]
        for pol in (P, [(5,77),(97,72),(97,76.5),(5,81.5)]): d.polygon([(x * S / 100, y * S / 100) for x, y in pol], fill=255)
    elif k == 'poly':  # arg = JSON file with [[x,y],...] (any scale) or a list of such lists
        pts = J(arg); pts = pts if isinstance(pts[0][0], list) else [pts]; allp = [p for q in pts for p in q]
        x0, y0, x1, y1 = min(p[0] for p in allp), min(p[1] for p in allp), max(p[0] for p in allp), max(p[1] for p in allp); sc = (S - 4) / max(x1 - x0, y1 - y0)
        for q in pts: d.polygon([((x - x0) * sc + 2, (y - y0) * sc + 2) for x, y in q], fill=255)
    elif k == 'text':  # lines separated by /
        lines = arg.split('/'); fs = 400
        while fs > 20:
            f = font(fs); bb = [d.textbbox((0, 0), l, font=f) for l in lines]
            if max(b[2] - b[0] for b in bb) <= S - 20 and sum(b[3] - b[1] + fs // 6 for b in bb) <= S * 1.4: break
            fs -= 8
        M = Image.new('L', (S, int(S * 1.4)), 0); d = ImageDraw.Draw(M); y = 10
        for l, b in zip(lines, bb): d.text(((S - (b[2] - b[0])) // 2 - b[0], y - b[1]), l, font=f, fill=255, stroke_width=fs // 25, stroke_fill=255); y += b[3] - b[1] + fs // 6
    elif k == 'image':  # silhouette from a picture: transparent PNG alpha, else the subject differing from the border colour; ':invert' flips
        inv = arg.endswith(':invert'); im = Image.open(arg.replace(':invert', '')); im.thumbnail((S, S))
        if im.mode in ('RGBA', 'LA') and np.asarray(im.getchannel('A')).min() < 128: a_ = np.asarray(im.getchannel('A')) > 128
        else:
            g = np.asarray(im.convert('L'), dtype=float); bd = np.median(np.concatenate([g[0], g[-1], g[:, 0], g[:, -1]])); a_ = abs(g - bd) > 40
        M = Image.fromarray((~a_ if inv else a_).astype('uint8') * 255)
    elif k == 'geojson':  # arg = file[#exact property value, e.g. a state or country name]; polygons only
        path, _, nm = arg.partition('#'); g = J(path); fe = g.get('features') or [g]
        if nm: fe = [f for f in fe if any(str(v).lower() == nm.lower() for v in (f.get('properties') or {}).values())] or die('no feature named ' + nm)
        polys = [p for f in fe for geo in [f.get('geometry', f)] for p in (geo['coordinates'] if geo['type'] == 'MultiPolygon' else [geo['coordinates']] if geo['type'] == 'Polygon' else [])]
        lat0 = np.mean([pt[1] for p in polys for pt in p[0]]); kx = math.cos(math.radians(lat0))
        xy = lambda p: [(pt[0] * kx, -pt[1]) for pt in p]; allp = [pt for p in polys for pt in xy(p[0])]
        x0, y0, x1, y1 = min(p[0] for p in allp), min(p[1] for p in allp), max(p[0] for p in allp), max(p[1] for p in allp); sc = (S - 4) / max(x1 - x0, y1 - y0)
        for p in polys:
            for i, ring in enumerate(p): d.polygon([((x - x0) * sc + 2, (y - y0) * sc + 2) for x, y in xy(ring)], fill=255 if i == 0 else 0)
    else: die('unknown shape ' + spec + ' (heart circle square star bird text:A/B image:FILE[:invert] geojson:FILE[#name] poly:FILE.json)')
    bb = M.getbbox() or die('empty shape mask'); return M.crop(bb)
def coverage(M, nc, nr): return np.asarray(M.resize((nc * 8, nr * 8), Image.BOX), dtype=float).reshape(nr, 8, nc, 8).mean(axis=(1, 3))
def dims(M, N): w, h = M.size; return (N, max(2, round(N * h / w))) if w >= h else (max(2, round(N * w / h)), N)
def shape_cells(spec, n, grid):
    M = shape_mask(spec)
    for N in ([grid] if grid else range(7, 81)):
        nc, nr = dims(M, N); cov = coverage(M, nc, nr); cells = [(c, r) for r in range(nr) for c in range(nc) if cov[r, c] >= 110]
        if len(cells) >= math.ceil(n * 1.2): break
    return nc, nr, cells

# ------------------------------------------------------------------ layout (existing tiles never move)
def kept(): return sorted([m for m in J('manifest.json', []) if m.get('idx') is not None], key=lambda m: m['idx'])
def new_layout(n):
    c = cfg(); nc, nr, cells = shape_cells(c['shape'], n, c['grid']); rng = random.Random(7); rng.shuffle(cells); ids = list(range(n)); rng.shuffle(ids); out = []; at = {}
    for i, (cc, rr) in enumerate(cells):
        if i < n: p, f = ids[i], 0
        else:
            f = 1
            for _ in range(8):
                p = rng.randrange(n)
                if p not in [at.get((cc + dx, rr + dy)) for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))]: break
        at[(cc, rr)] = p; out.append([cc, rr, p, f])
    extra = ids[len(cells):]                              # more photos than shape cells: grow outward
    L = dict(nc=nc, nr=nr, cells=out); [place(L, p) for p in extra]; return L
def place(L, p):
    """put photo p on a filler cell (replacing the repeat), else grow the silhouette outward; never moves real tiles"""
    fill = [t for t in L['cells'] if t[3]]
    if fill: t = random.Random(p).choice(fill); t[2], t[3] = p, 0; return
    occ = {(t[0], t[1]) for t in L['cells']}; cx = np.mean([t[0] for t in L['cells']]); cy = np.mean([t[1] for t in L['cells']]); best = None
    for r in range(L['nr']):
        for c in range(L['nc']):
            if (c, r) in occ: continue
            nb = sum((c + dx, r + dy) in occ for dx in (-1, 0, 1) for dy in (-1, 0, 1) if dx or dy)
            if nb and (best is None or (nb, -math.hypot(c - cx, r - cy)) > best[0]): best = ((nb, -math.hypot(c - cx, r - cy)), c, r)
    if not best: die('grid is full: run `python3 gallery.py build --regrid` (re-shuffles all tiles into a bigger grid), then deploy')
    L['cells'].append([best[1], best[2], p, 0])

# ------------------------------------------------------------------ apply decisions
STATE = ['config.json', 'manifest.json', 'layout.json']
def backup():
    d = 'backup/' + time.strftime('%Y%m%d-%H%M%S'); os.makedirs(d + '/site', exist_ok=True)
    for f in STATE:
        if os.path.exists(f): shutil.copy2(f, d)
    for f in ('index.html', 'tiles.json', 'card.png', 'atlas.jpg'):
        if os.path.exists('site/' + f): shutil.copy2('site/' + f, d + '/site')
    for old in sorted(os.listdir('backup'))[:-5]: shutil.rmtree('backup/' + old)
    return d
def cmd_rollback(a):
    d = a.dir or 'backup/' + sorted(os.listdir('backup'))[-1]
    for f in STATE:
        if os.path.exists(d + '/' + f): shutil.copy2(d + '/' + f, f)
    log('restored', d); cmd_build(argparse.Namespace(regrid=False))
def cmd_apply(a):
    pend = J('pending.json') or die('no pending.json (run fetch)'); dec = J(a.decisions) or die('no decisions file')
    miss = [x['n'] for x in pend if str(x['n']) not in dec and not x['suggest_dup']]
    if miss: die(f'decisions missing for n={miss} (use "skip" or a short category label)')
    b = None if a.dry_run else backup(); log('backup', b)
    try:
        man = J('manifest.json', []); idx = len([m for m in man if m.get('idx') is not None]); L = J('layout.json'); first = L is None; new = []
        for x in pend:
            v = dec.get(str(x['n']), 'skip'); m = {k: x[k] for k in ('key', 'post_id', 'date', 'file', 'link', 'sha256', 'phash', 'dhash', 'src')}
            m['decision'] = 'skip' if v == 'skip' else 'keep'
            if v != 'skip': m['idx'] = idx; m['cat'] = v; new.append(idx); idx += 1
            man.append(m)
        if a.dry_run: log('dry run:', len(new), 'would be added'); return
        dump(man, 'manifest.json', indent=1)
        if new:
            if first: L = new_layout(idx)
